INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4604f8f2-262c-4568-bf7d-3e8ef5b2145a', 'a99fedd9-d59e-4b89-9e08-667cfc38c4e5', 0, 'pause (default), continue, and rollback');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9d64c6cd-7955-400c-8a68-5c4edc9755b7', 'a99fedd9-d59e-4b89-9e08-667cfc38c4e5', 1, 'stop, restart, and retry');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1aad7160-c57c-4535-8082-36b6a6e915af', 'a99fedd9-d59e-4b89-9e08-667cfc38c4e5', 2, 'abort, skip, and force');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d008a4e-27a3-4de7-8ae2-45455d62428b', 'a99fedd9-d59e-4b89-9e08-667cfc38c4e5', 3, 'wait, escalate, and terminate');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
