INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('98d01ea3-790a-480e-b1b5-80053ae54569', 'ec504618-c109-406f-b4b6-62f868ca0ec1', 0, 'The fraction of tasks that failed to update successfully exceeds the threshold set by `--update-max-failure-ratio`');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4b31dd85-6214-4e5e-953c-dcde0174248d', 'ec504618-c109-406f-b4b6-62f868ca0ec1', 1, 'Any single task failure, regardless of the configured failure ratio');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('460d15dc-25d6-4535-b5ec-a209f5bb5424', 'ec504618-c109-406f-b4b6-62f868ca0ec1', 2, 'The update simply running longer than `--update-monitor`''s duration');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('807bae20-2b4a-48f6-8b13-615e30d3f27b', 'ec504618-c109-406f-b4b6-62f868ca0ec1', 3, 'A manual `docker service rollback` command must always be issued first, even with this flag set');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a51dc46a-2e70-4c2d-bb6e-4f0fe3694e04', '623b5c79-7fcf-4599-a161-86e3b6eac5a0', 0, 'Swarm starts the new task and waits for it to become healthy BEFORE stopping the corresponding old task, briefly running both versions side-by-side — useful for avoiding downtime, at the cost of temporarily needing extra resource capacity');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e5c7f511-df0a-474e-a6e1-9c61a75432bc', '623b5c79-7fcf-4599-a161-86e3b6eac5a0', 1, 'It updates all tasks simultaneously instead of in batches');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a79c4e5e-3c83-48f3-b6af-c3bef21a221f', '623b5c79-7fcf-4599-a161-86e3b6eac5a0', 2, 'It reverses the update to always process the newest-created task first');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aad88f4c-8bea-40ce-8462-5312f535fab9', '623b5c79-7fcf-4599-a161-86e3b6eac5a0', 3, 'It disables health checks during the update entirely');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e33c1fd4-7b22-4906-8a69-d646f299acdd', '254e5b40-9874-4cb6-88ea-41d7751319e6', 0, 'Normal rolling updates proceed cautiously, one task at a time, but if a rollback is triggered, it happens faster by reverting three tasks at a time');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e2b8244-27a6-4fdf-b408-ea45103e2387', '254e5b40-9874-4cb6-88ea-41d7751319e6', 1, 'Updates happen 3 tasks at a time, but rollbacks are forced to happen 1 task at a time for safety');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3fc80b39-3cba-471d-9f4c-b5159f203dbf', '254e5b40-9874-4cb6-88ea-41d7751319e6', 2, 'The rollback-parallelism value is ignored unless update-parallelism is also set to 3');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0617e5b3-87d3-41ab-8f86-6e8ff7873b56', '254e5b40-9874-4cb6-88ea-41d7751319e6', 3, 'This configuration is invalid; the two values must always match');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1b421b26-169d-42e5-a318-317162bb7000', 'fa1c6cc0-17d7-4af3-aa60-45a86feecf54', 0, '`docker service update --rollback <service>` (or the shorthand `docker service rollback <service>`), which reverts the service to its previously recorded specification');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('11b1375f-640f-4fbe-8ccc-ec5ba3ad8283', 'fa1c6cc0-17d7-4af3-aa60-45a86feecf54', 1, 'Manually re-running the exact previous `docker service create` command, since Swarm keeps no history of prior specs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b3a42f6b-0ea1-419f-9149-b8296846125f', 'fa1c6cc0-17d7-4af3-aa60-45a86feecf54', 2, 'Deleting and recreating the service from a backed-up Compose file only — there is no live rollback mechanism');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b98c242d-3905-4ad4-8710-ec23d433c082', 'fa1c6cc0-17d7-4af3-aa60-45a86feecf54', 3, '`docker service pause <service>` followed by a manual re-image of every task');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('07aef15f-d01b-45a5-b0e9-1f94e769f362', 'f550c50d-18a6-4743-87ca-14d5ea32044c', 0, 'How long Swarm waits after updating each task before deciding whether that task''s update actually succeeded or failed, before moving on to the next batch');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dd2c25ee-3592-427a-ab50-93ea19a5e8cc', 'f550c50d-18a6-4743-87ca-14d5ea32044c', 1, 'The total maximum time allowed for the entire rolling update across all tasks combined');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8555b9df-2e58-485a-b6f2-0b6c776f73db', 'f550c50d-18a6-4743-87ca-14d5ea32044c', 2, 'How often the CLI polls and prints progress output to the terminal');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e714966d-68bd-4034-ad12-6dfe6eee49cd', 'f550c50d-18a6-4743-87ca-14d5ea32044c', 3, 'The TTL for the service''s DNS entry during the update window');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('761afbcf-cfac-4833-837c-a045aa566e53', 'fc74fe38-0324-4690-a3f0-9fb2f56554b4', 0, 'The pause Swarm inserts between updating one batch of tasks (per --update-parallelism) and starting the next batch');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f5935d8f-64bb-4678-82be-2e9fcdd8c7f1', 'fc74fe38-0324-4690-a3f0-9fb2f56554b4', 1, 'The delay before the very first task in the update begins, only');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0a6a1856-d932-4cfa-b839-45dd5ea0c4b2', 'fc74fe38-0324-4690-a3f0-9fb2f56554b4', 2, 'The delay before Swarm even accepts the `docker service update` command');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e87fdbd-385c-4f5d-8a82-80f8e695050b', 'fc74fe38-0324-4690-a3f0-9fb2f56554b4', 3, 'The DNS propagation delay for the service''s virtual IP');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7856dac3-ba7a-4325-b75f-f03afbcc802b', '5bd0f1eb-10ae-478c-af9a-85c91856cfc8', 0, '--constraint ''node.role==manager''');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f4857ca4-9f7a-4506-9466-a2ec610b182b', '5bd0f1eb-10ae-478c-af9a-85c91856cfc8', 1, '--constraint ''node.type==master''');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ea340e96-90b5-4e7b-836f-d3bb8266775e', '5bd0f1eb-10ae-478c-af9a-85c91856cfc8', 2, '--constraint ''swarm.manager==true''');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('078e3461-871b-427e-b129-889ceb07087c', '5bd0f1eb-10ae-478c-af9a-85c91856cfc8', 3, '--constraint ''node.primary==yes''');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('35972359-04df-4ca5-8be5-ad1721404668', '2f49386f-6af4-4819-9d10-b4e656fe29f6', 0, '--constraint ''node.labels.zone==us-east''');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1797386e-909c-4655-9aaf-e4f4d04700f5', '2f49386f-6af4-4819-9d10-b4e656fe29f6', 1, '--constraint ''zone==us-east''');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bfad26b9-ed84-4b34-9b86-7bc3ee171cf6', '2f49386f-6af4-4819-9d10-b4e656fe29f6', 2, '--label ''zone==us-east''');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c8c50913-7ec1-41da-bb5b-fd8c168f2381', '2f49386f-6af4-4819-9d10-b4e656fe29f6', 3, '--constraint ''engine.labels.zone==us-east''');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8d3719da-1c93-4256-9388-f237b6d62699', '2b77f4f5-1d45-48b7-8746-d9f01ca33482', 0, 'engine.labels reads labels set on the Docker Engine daemon itself (via daemon.json or dockerd flags on that host), while node.labels reads labels Swarm-management assigned to the node object via `docker node update --label-add` — they''re set through entirely different mechanisms');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5620248d-ea67-4fa6-aa5b-45f5b118889d', '2b77f4f5-1d45-48b7-8746-d9f01ca33482', 1, 'They are synonyms with no functional difference');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('245c0b90-ad80-46e5-b1db-50af861a592d', '2b77f4f5-1d45-48b7-8746-d9f01ca33482', 2, 'engine.labels only applies to worker nodes; node.labels only applies to managers');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cd2fc2fd-7103-4809-aa20-92fd2015c38d', '2b77f4f5-1d45-48b7-8746-d9f01ca33482', 3, 'engine.labels is deprecated and always empty in current Docker versions');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('15afc80a-6361-40eb-9533-508c3cbbfd8e', '631c611a-859e-4e5b-a28b-ac1cfa69cdab', 0, 'With AND logic — a node must satisfy ALL specified constraints simultaneously to be eligible for task placement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c059398a-8934-4421-85a7-c1df7459226b', '631c611a-859e-4e5b-a28b-ac1cfa69cdab', 1, 'With OR logic — a node satisfying any one of the constraints is eligible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9e766e9a-57f9-4f76-b51c-aeedf001a6ea', '631c611a-859e-4e5b-a28b-ac1cfa69cdab', 2, 'Only the last --constraint flag specified takes effect; earlier ones are overridden');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b5525f4e-1803-4345-910f-3cb0893ef686', '631c611a-859e-4e5b-a28b-ac1cfa69cdab', 3, 'Multiple --constraint flags on the same service are rejected as invalid syntax');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e7fcfa62-7711-48d5-b64d-d182e831b755', '667d47d4-47f3-4835-a5c4-8cd86c2e9040', 0, 'Only place tasks on nodes where the role is NOT worker (i.e., effectively manager nodes) — != is a valid constraint operator alongside ==');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('be80ce6a-0df7-458b-a440-fe8aafc178b0', '667d47d4-47f3-4835-a5c4-8cd86c2e9040', 1, 'This is invalid syntax; only == is supported for constraints');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('98d07f8b-d561-436e-acf8-827c0e114442', '667d47d4-47f3-4835-a5c4-8cd86c2e9040', 2, 'It excludes the constraint from being evaluated at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a38f24b3-290d-4dd0-85e9-0883da980b4a', '667d47d4-47f3-4835-a5c4-8cd86c2e9040', 3, 'It places tasks preferentially, but not exclusively, away from worker nodes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f1d35fa5-15be-4091-93a9-27c3886d98d6', 'ac590ac9-d105-46c4-8f0f-12c49b9d47ec', 0, 'A preference is a soft/best-effort hint that influences how tasks are spread across nodes (e.g. evenly across zones) without excluding any node outright, whereas a constraint is a hard requirement that excludes non-matching nodes entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8c7bb9d5-d864-4420-909e-8e6937479c36', 'ac590ac9-d105-46c4-8f0f-12c49b9d47ec', 1, 'Preferences and constraints are functionally identical; --placement-pref is just older syntax for --constraint');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c2da9cf9-a7e2-4c91-b37e-cbe3498228d7', 'ac590ac9-d105-46c4-8f0f-12c49b9d47ec', 2, 'A preference guarantees perfectly equal distribution across all matching values, with no exceptions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('abd1706f-0e87-416f-b864-daf91d07225a', 'ac590ac9-d105-46c4-8f0f-12c49b9d47ec', 3, 'Preferences can only be used for global mode services, never replicated services');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('53d874f7-1fef-4b92-8ea6-73450ce62cce', '76a949f0-b2ef-4e3e-9494-9676dc027a1a', 0, 'The maximum number of this service''s tasks that may be scheduled onto any single node, preventing over-concentration of replicas on one host');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('66c0fe2c-c338-44f3-9dc5-d020e80c4ff9', '76a949f0-b2ef-4e3e-9494-9676dc027a1a', 1, 'The total maximum replica count for the entire service across the whole cluster');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c7c9821f-0313-4824-9939-66f0983485df', '76a949f0-b2ef-4e3e-9494-9676dc027a1a', 2, 'The maximum number of different services allowed to run on one node');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e99afebe-3a35-4379-964c-a776330a87d6', '76a949f0-b2ef-4e3e-9494-9676dc027a1a', 3, 'The maximum number of manager nodes allowed to host any task of this service');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('698f26ef-6184-480d-8ad3-95d933dfc36d', '98e31177-6c29-4992-b2b6-1f4b8dc6e42b', 0, 'Creates a Swarm ''config'' object named app_config from the local file''s contents, which can then be attached to one or more services');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ac318569-1b3a-4188-a6e9-3894ab3b4676', '98e31177-6c29-4992-b2b6-1f4b8dc6e42b', 1, 'Creates a new Swarm secret, since configs and secrets share the same underlying command with different flags');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3cbdab06-1b5c-4cab-b46b-b5126019c239', '98e31177-6c29-4992-b2b6-1f4b8dc6e42b', 2, 'Immediately mounts the file into every currently-running service on the cluster');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('15768857-f012-44a1-8ca5-b5e1ed684159', '98e31177-6c29-4992-b2b6-1f4b8dc6e42b', 3, 'Validates the file as a syntactically correct nginx configuration before accepting it');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ceb5ce5c-77f2-4adf-82c0-7b3ab22578cd', '44281b51-fd23-4fc3-a48c-4e48e7f3be78', 0, 'The `target` parameter — it explicitly sets the in-container mount path, which can differ from the config''s own name');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8df186dd-0d13-4dda-b70a-0b611bc6b228', '44281b51-fd23-4fc3-a48c-4e48e7f3be78', 1, 'The config is always mounted at /run/configs/<config-name>, with no way to override the path');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('147f93ae-10b5-4fa1-bbb4-03b0fdf1d17f', '44281b51-fd23-4fc3-a48c-4e48e7f3be78', 2, 'The target parameter only works for secrets, not configs — configs always mount at their source name under /');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aa0896fc-2a8f-4afb-a356-07496281247e', '44281b51-fd23-4fc3-a48c-4e48e7f3be78', 3, 'The container''s WORKDIR determines the mount path automatically');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('37dc2601-d28e-442e-885c-1d0d24fc45fd', '1d7f6319-a5f2-478d-8779-0fe2d9583d38', 0, 'The config is automatically delivered to whichever node the rescheduled task lands on — configs (like secrets) are Swarm-cluster-scoped resources, not tied to a specific node''s local filesystem');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5c7c7f4e-413e-4e26-8d1a-9887241bc50a', '1d7f6319-a5f2-478d-8779-0fe2d9583d38', 1, 'The task fails to start on the new node unless the config file was manually copied there first');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a37c7df6-99d9-466a-9bd7-3b0352cca00f', '1d7f6319-a5f2-478d-8779-0fe2d9583d38', 2, 'The config is lost permanently and must be recreated');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1a5701f3-355e-472a-9995-c00290e0c2d8', '1d7f6319-a5f2-478d-8779-0fe2d9583d38', 3, 'The task starts, but with an empty file at the target path until manually re-synced');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('633a5743-f3ab-440c-9b49-bcd32a4d6525', '8c9174ad-254c-4e08-b9bd-4ec961e1ac50', 0, 'The secret is expected to already exist in the Swarm (created beforehand via `docker secret create`), and `docker stack deploy` should reference it rather than try to create it from a file/inline value');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ed976eaa-9724-434d-b0ac-93499def3f5b', '8c9174ad-254c-4e08-b9bd-4ec961e1ac50', 1, 'The secret''s value is fetched from an external HTTPS endpoint at every task start');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('65da0e43-2fdb-4e89-a2b4-7f555c84418a', '8c9174ad-254c-4e08-b9bd-4ec961e1ac50', 2, 'The secret is shared externally with other Swarm clusters automatically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1eda08cd-e651-4fdb-834c-59b8da493405', '8c9174ad-254c-4e08-b9bd-4ec961e1ac50', 3, 'external: true disables encryption for that specific secret');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c185710d-b1d7-404b-a4d2-b37b1517f7ed', 'dd8ef761-1a20-4363-a53f-74a8899d24f7', 0, 'mystack_db_password — stack deploy prefixes top-level secret/config names with the stack name to avoid collisions between stacks reusing the same short name');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6d5ec6a7-c857-4928-b220-c76ca8321b59', 'dd8ef761-1a20-4363-a53f-74a8899d24f7', 1, 'db_password, exactly as written, with no prefixing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cfd6a63c-3a72-46fe-920b-f6b1d1da58d6', 'dd8ef761-1a20-4363-a53f-74a8899d24f7', 2, 'A randomly generated UUID, unrelated to the Compose-file name');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a3bca227-76ce-456e-9fc6-2f1d962a9f02', 'dd8ef761-1a20-4363-a53f-74a8899d24f7', 3, 'It depends on the Compose file''s `version:` key; only version 3.9+ applies the stack-name prefix');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2e6ca69d-9f0c-492b-a461-cb7a66e536ef', 'af1de60d-a6cb-4306-9ff8-b897574ac26e', 0, 'Create a new config object under a new name (e.g. app_config_v2) from the updated file, then `docker service update --config-rm app_config --config-add source=app_config_v2,target=<path> <service>` to swap it in, triggering a rolling redeploy of the service''s tasks');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ff45b14a-cb66-4a2f-ae11-400958a68c4d', 'af1de60d-a6cb-4306-9ff8-b897574ac26e', 1, 'Overwrite the original file on disk; Swarm automatically detects the file change and re-syncs it to all tasks live');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ee71bd37-53a8-4e94-bcda-11d0947b57db', 'af1de60d-a6cb-4306-9ff8-b897574ac26e', 2, 'Run `docker config update app_config ./new-nginx.conf` to update its content in place');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ee55edc5-0bf9-44c8-927c-d0dda372a38c', 'af1de60d-a6cb-4306-9ff8-b897574ac26e', 3, 'Restart the Docker daemon on each node to force a config re-read');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c83ef20e-c0a0-4500-98d6-3336e5ce53b0', 'cea6b5a1-b63f-404d-ac44-07a68d8bbbb7', 0, 'Version 3 (e.g. version: ''3'' or higher) — stacks require the version-3.x schema, which added Swarm-specific keys like `deploy:`');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5ffc9822-32c3-4bd8-b77f-f3be5d3e043b', 'cea6b5a1-b63f-404d-ac44-07a68d8bbbb7', 1, 'Version 1, the original Compose format');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c580054f-4171-4232-aa46-106d3f561116', 'cea6b5a1-b63f-404d-ac44-07a68d8bbbb7', 2, 'Version 2, since it introduced named networks');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('06739d84-7023-4e06-ad02-d07abf051859', 'cea6b5a1-b63f-404d-ac44-07a68d8bbbb7', 3, 'Stacks work with any version, including version 1, since stack deploy silently ignores unsupported keys');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a1395dea-a612-4f2b-9278-a5931dad6159', '9e5af0fc-28b7-48c7-bdc7-fdb4d821551e', 0, 'The build: key is ignored — `docker stack deploy` does not build images; the service must already reference a pre-built image available to every node (typically via a registry), and stack deploy will fail or behave unexpectedly if no valid image: is resolvable');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('652ac968-8c7b-4a93-9719-8da0781d9c5b', '9e5af0fc-28b7-48c7-bdc7-fdb4d821551e', 1, 'Swarm automatically builds the image on the manager node and distributes it to all workers');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('624318b6-7f32-4aa0-a246-3866c57ed047', '9e5af0fc-28b7-48c7-bdc7-fdb4d821551e', 2, 'Each worker node independently builds the image locally before starting its own tasks');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dc113777-f610-4f67-866d-5ba3d6d45648', '9e5af0fc-28b7-48c7-bdc7-fdb4d821551e', 3, 'docker stack deploy delegates the build to Docker Hub automatically');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a4631fc8-4561-4195-8dbb-64917ea00d4a', 'c0c6e699-0d43-4dd5-8e33-6a2f5e145a25', 0, 'Stack deploy creates a default overlay network scoped to that stack, and attaches every service in the stack to it automatically, letting services reach each other by service name');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('af5463a0-02e9-42a7-a0d9-3ebb483c7e6f', 'c0c6e699-0d43-4dd5-8e33-6a2f5e145a25', 1, 'All services fall back to using the host network directly');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e063ca02-d175-4440-944a-d53b3459f5df', 'c0c6e699-0d43-4dd5-8e33-6a2f5e145a25', 2, 'Services get no network at all and cannot communicate unless a network is explicitly declared');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('34b8d9ac-3a2f-4d7b-9de4-cb565a9ba0ec', 'c0c6e699-0d43-4dd5-8e33-6a2f5e145a25', 3, 'Services are attached to the default `bridge` network, identical to standalone docker run containers');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aaad6b8d-a95e-4e26-a8a7-b1e955b05b0a', '0015b1d3-33c3-4bbe-833f-71ab581ce942', 0, 'The individual tasks (with their current/desired state, node placement, and any recent error) across every service in the stack — a more granular view than the per-service summary `stack services` gives');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f952bf03-0ed1-4881-9cd1-c1edf869431c', '0015b1d3-33c3-4bbe-833f-71ab581ce942', 1, 'The exact same output as `docker stack services`, just with different column ordering');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9d3dc7ff-92a4-46bc-a243-14391a3b8dd3', '0015b1d3-33c3-4bbe-833f-71ab581ce942', 2, 'Only tasks that have failed, filtering out running ones');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('26189c3b-4e6c-42c8-a1ab-30391101d19b', '0015b1d3-33c3-4bbe-833f-71ab581ce942', 3, 'The historical list of every docker stack deploy invocation ever run against that stack name');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('624f1021-d02f-4175-9994-660e3565df07', '5f5a00b5-9506-4d28-9ece-0776591df8db', 0, 'Re-run `docker stack deploy -c compose.yml mystack` with the same stack name — stack deploy is declarative and reconciles the running stack toward the new file''s desired state, updating only what changed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d6aa1911-a94b-4a16-a93e-985c891386a5', '5f5a00b5-9506-4d28-9ece-0776591df8db', 1, 'Run `docker stack rm mystack` first, then deploy fresh — in-place stack updates are not supported');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('22f92631-68d4-4b48-b773-efffd3a856cc', '5f5a00b5-9506-4d28-9ece-0776591df8db', 2, 'Manually run `docker service update` against each affected service individually; stack deploy cannot be re-run on an existing stack');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('144bcb9d-a459-4ba9-897d-288dd4058fb8', '5f5a00b5-9506-4d28-9ece-0776591df8db', 3, 'Restart the Swarm manager nodes to force a re-read of the Compose file');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5b9541b3-f31e-482f-bbdd-554311896d24', '065a6033-a19e-413b-8e13-ab2a51e19db8', 0, 'mystack_web — stack deploy prefixes service (and most other resource) names with the stack name to avoid collisions across stacks');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('701a1e89-cc4f-4113-a08e-ee51073945a7', '065a6033-a19e-413b-8e13-ab2a51e19db8', 1, 'web, exactly as declared, with no prefixing applied to service names specifically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8900c228-cdff-4136-92fb-bd7e48d9a028', '065a6033-a19e-413b-8e13-ab2a51e19db8', 2, 'A randomly generated name unrelated to either the stack or service name');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('93cf3cf3-b66b-4adb-a84f-88f8cb00610b', '065a6033-a19e-413b-8e13-ab2a51e19db8', 3, 'mystack-web, using a hyphen rather than an underscore separator');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7fd23533-db52-4739-956b-73491dec8b9e', 'eea8655b-6c71-4ea5-b222-b5ab34add9ed', 0, 'Every Swarm resource stack deploy created and attributed to that stack — its services, its stack-scoped networks, and (in current Docker versions) its stack-scoped secrets/configs — but NOT any external:true secrets/configs it only referenced');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ed53521a-f7ef-4bd5-be57-75c8caada657', 'eea8655b-6c71-4ea5-b222-b5ab34add9ed', 1, 'Only the stack''s services; networks, secrets, and configs must be removed manually afterward in every case');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2c4c892a-77de-400f-a028-fdce4e5d9e58', 'eea8655b-6c71-4ea5-b222-b5ab34add9ed', 2, 'The entire Swarm cluster''s configuration, resetting it to an unmanaged state');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2926669d-3a21-4eba-a817-e07d90570f04', 'eea8655b-6c71-4ea5-b222-b5ab34add9ed', 3, 'Only stops the stack''s tasks without deleting the service definitions, so `docker stack deploy` on the same name resumes instantly with no reconciliation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('13731ca0-7feb-4516-9fa9-7353447f3f60', 'd809071c-08b2-4f75-9dda-acbc8239f5db', 0, '`docker network create --opt encrypted --driver overlay <name>`, which applies IPSEC encryption at the VXLAN level for that network''s data traffic');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('38f76c7e-b64a-459d-9c42-4748a0a5dcf3', 'd809071c-08b2-4f75-9dda-acbc8239f5db', 1, 'Overlay networks are always encrypted by default; no flag is needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('82b61489-2703-467b-ac00-a8a2a942e140', 'd809071c-08b2-4f75-9dda-acbc8239f5db', 2, 'By setting `--encrypt-daemon` when starting dockerd, which encrypts every network cluster-wide');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3579eac4-c83a-47e5-98f9-de3b96f70e7e', 'd809071c-08b2-4f75-9dda-acbc8239f5db', 3, 'By attaching a `tls=true` label to each service using the network');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c64c25d9-8795-455b-a6e1-e42b5f4534e5', 'aeba9dbc-c3b3-48e2-9eaa-970eb5b503e5', 0, 'A non-negligible performance penalty from the IPSEC encryption/decryption overhead, so it''s recommended to test the impact before using it in production, and it isn''t supported for Windows containers on that network');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('04c870b4-d95e-4888-92c5-1977ab1ba247', 'aeba9dbc-c3b3-48e2-9eaa-970eb5b503e5', 1, 'It doubles the number of manager nodes required for quorum');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('935dfd3c-ddde-4b47-b693-e4fdd00a73ac', 'aeba9dbc-c3b3-48e2-9eaa-970eb5b503e5', 2, 'It disables the routing mesh for any service attached to that network');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b822d5f8-4855-4132-9c1c-a589d24815c3', 'aeba9dbc-c3b3-48e2-9eaa-970eb5b503e5', 3, 'It requires switching the entire cluster from VXLAN to a different tunneling protocol');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b86d5a5b-5f9e-4e90-92dc-a7dab934625a', 'c1dcd024-52ed-4238-8182-07cdeadd0daf', 0, '`docker swarm init` (and joining nodes via `docker swarm join`) automatically creates it; it handles control/data traffic for the routing mesh, and any service published without attaching a user-defined overlay network uses it by default');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('79c1eacb-3f2e-4290-b757-4c7ec7eb0633', 'c1dcd024-52ed-4238-8182-07cdeadd0daf', 1, 'An administrator must manually run `docker network create ingress` after initializing the swarm');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3303eef3-f510-47a6-aeaf-de37094facfb', 'c1dcd024-52ed-4238-8182-07cdeadd0daf', 2, 'It''s created only when the first service is published with -p, and is deleted after that service is removed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fe8e4d3c-a5e9-46e0-b6ac-068f8f9a4e5b', 'c1dcd024-52ed-4238-8182-07cdeadd0daf', 3, 'It exists only on manager nodes, never on workers');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d5dab760-632f-412f-8120-e792788b15ce', '995f7217-6d07-441c-b06b-0bcc3749b8e4', 0, 'Standalone containers (not just Swarm service tasks) can be explicitly attached to that overlay network via `docker run --network`, letting non-service containers communicate with Swarm services on it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c518b3a5-6003-4906-8baa-4b22c7c5d93d', '995f7217-6d07-441c-b06b-0bcc3749b8e4', 1, 'It allows the network to span multiple separate Swarm clusters');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3ccc6565-f170-482d-9982-44835cb35a00', '995f7217-6d07-441c-b06b-0bcc3749b8e4', 2, 'It converts the overlay network into a bridge network automatically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a2fea49-7b67-4f09-8059-08157f0b3bea', '995f7217-6d07-441c-b06b-0bcc3749b8e4', 3, 'It''s required before any service can use the network at all — non-attachable overlay networks reject all connections');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cbfc2885-5066-4ec6-aa70-edbb5483121f', 'db644d4d-f033-4d60-877b-d9ca756f99d8', 0, 'UDP port 4789 (VXLAN)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e4592501-e6e0-4118-bcdb-5d49f0d120b7', 'db644d4d-f033-4d60-877b-d9ca756f99d8', 1, 'TCP port 443 (HTTPS)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4bc988f0-f997-4a48-bafc-433728f62f13', 'db644d4d-f033-4d60-877b-d9ca756f99d8', 2, 'TCP port 2376 (Docker daemon TLS)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0af5be2a-8c73-437d-b0ec-db267e15a68c', 'db644d4d-f033-4d60-877b-d9ca756f99d8', 3, 'UDP port 53 (DNS)');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f0b559c7-8c81-4000-9ae3-440e41a6bcfc', 'eb9d275c-a063-42d0-9bc8-70c544863424', 0, 'overlay networks span multiple Docker hosts, enabling containers/tasks on different nodes to communicate directly as if on the same network; bridge networks are confined to a single host');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2d8abb73-5b34-4cc6-9155-a4c285ac6426', 'eb9d275c-a063-42d0-9bc8-70c544863424', 1, 'bridge networks span multiple hosts; overlay networks are single-host only');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5d2e2524-0d1e-4549-b667-826354cea5fd', 'eb9d275c-a063-42d0-9bc8-70c544863424', 2, 'They are functionally identical, differing only in name');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('626ce533-514e-49bf-89b9-8de7e3f2ad16', 'eb9d275c-a063-42d0-9bc8-70c544863424', 3, 'overlay is used exclusively for Kubernetes workloads under MKE, never for Swarm');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0db30d91-6e27-48d4-a6f3-bbfed245434b', '7b83713b-7b6d-4ce6-9140-485d15de802e', 0, 'A 1:1:1 mapping of subject (a user, organization, team, or service account) + role + resource set — defining who has how much access to what');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4a1dd23e-c4cf-4fef-827b-6809c7a8616c', '7b83713b-7b6d-4ce6-9140-485d15de802e', 1, 'A single global on/off switch for cluster-wide admin access');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7a1d89b7-fdb4-4df7-8509-1313c559abeb', '7b83713b-7b6d-4ce6-9140-485d15de802e', 2, 'A time-limited access token issued for a single API call');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8685f948-9320-4fee-b2d4-2a37b1146c73', '7b83713b-7b6d-4ce6-9140-485d15de802e', 3, 'A synonym for a Kubernetes ClusterRoleBinding, with no Swarm equivalent');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b4ae70ad-8345-4a46-b9e1-82286c78093c', '9c6c0707-b010-41ff-ab2c-1d37ac8498c1', 0, 'Swarm resources are grouped into ''collections''; Kubernetes resources are grouped into namespaces — the two orchestrators use different resource-grouping concepts within the same overall grant model');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('348f6546-2bd7-42d0-bd55-31d427f6bb53', '9c6c0707-b010-41ff-ab2c-1d37ac8498c1', 1, 'Both Swarm and Kubernetes resources use identical ''namespace'' grouping, with no separate Swarm-specific concept');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9e325461-bd81-42f5-99f5-5efef056f486', '9c6c0707-b010-41ff-ab2c-1d37ac8498c1', 2, 'Resources cannot be grouped at all in MKE; every grant must name individual resources one at a time');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ac506ea8-a6ed-431e-8bd3-b25e3a344786', '9c6c0707-b010-41ff-ab2c-1d37ac8498c1', 3, 'Collections and namespaces are purely cosmetic labels with no actual effect on grant scope');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('287d52bb-f06f-4432-a053-74e8fec642b4', '35b31c62-d8e2-4b48-9b4e-ae013fd76aac', 0, 'A team is a subgroup within an organization; when granting access to an organization-based subject, an administrator can optionally narrow the grant to one specific team within that organization rather than the whole organization');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('135783f5-a2ec-4460-a61f-0fef6dd92d78', '35b31c62-d8e2-4b48-9b4e-ae013fd76aac', 1, 'Teams and organizations are interchangeable terms for the exact same object');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('16c762f7-e1b4-4ec2-b3c2-a382e9c228bb', '35b31c62-d8e2-4b48-9b4e-ae013fd76aac', 2, 'A team can span multiple organizations, but an organization cannot contain multiple teams');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2a20f724-d4d2-4e70-a40e-bcf7b1cdfb76', '35b31c62-d8e2-4b48-9b4e-ae013fd76aac', 3, 'Teams only exist for Kubernetes-orchestrated resources, never for Swarm collections');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a944b98-726c-47b5-80b3-e3e1964210fd', 'caa356a3-d9ec-44b9-b64e-49e2890e483a', 0, 'Service accounts — allowing automated/non-human clients (e.g. a CI pipeline) to be granted scoped access the same way a human user or team would be');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fe11cc96-bfcc-497c-9c4f-0161f382201a', 'caa356a3-d9ec-44b9-b64e-49e2890e483a', 1, 'Only Kubernetes Pods directly, never an account abstraction');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eae4920c-68f3-4497-a6b4-1519fbab02ff', 'caa356a3-d9ec-44b9-b64e-49e2890e483a', 2, 'Only the built-in ''admin'' role, which cannot be reassigned');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c384ddf9-4c15-411b-9777-7396da477a06', 'caa356a3-d9ec-44b9-b64e-49e2890e483a', 3, 'Physical worker nodes themselves, as if they were users');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0f1f4b81-a214-44aa-80c4-bde200ccedaf', '87163114-7b03-4817-85e7-25c79bfe834c', 0, 'Default roles are pre-built permission sets MKE ships with out of the box (e.g. read-only, restricted-control, full-control); custom roles let an administrator define their own permitted API operations per resource type when the defaults don''t match a needed access level');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3db91687-caf1-4e10-b8f1-033fb22086d5', '87163114-7b03-4817-85e7-25c79bfe834c', 1, 'Default roles apply only to Kubernetes; custom roles apply only to Swarm');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4402273d-c989-428c-8e77-8db8aac05e0d', '87163114-7b03-4817-85e7-25c79bfe834c', 2, 'Custom roles can only reduce a default role''s permissions, never add new ones');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e7926ddc-f191-4f46-85b6-ec43ae084287', '87163114-7b03-4817-85e7-25c79bfe834c', 3, 'There is no functional difference; ''custom role'' is just a display-name alias for a chosen default role');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e8a74d18-3ac4-4d9f-b0c2-f89121f1a521', '9cf34129-f6e3-4e04-8cd7-7cf8f23ae829', 0, 'It applies the chosen role binding across ALL namespaces in the cluster, rather than scoping the grant to a single selected namespace');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c7cfd50c-8578-4b85-a646-501d03556f3a', '9cf34129-f6e3-4e04-8cd7-7cf8f23ae829', 1, 'It converts the grant into a Swarm-collection-based grant instead of a namespace-based one');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4c797d17-9605-453a-85ef-42d0070ec1ea', '9cf34129-f6e3-4e04-8cd7-7cf8f23ae829', 2, 'It immediately deletes any existing namespace-scoped grants for that same subject');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4224c325-a488-4b13-8e25-a12fc86c1ea6', '9cf34129-f6e3-4e04-8cd7-7cf8f23ae829', 3, 'It has no functional effect; it''s purely a UI label');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
